begin;
select plan(41);
select has_table('public','blood_donors','blood donors are facility scoped');
select has_table('public','blood_units','unit inventory is tracked');
select has_table('public','blood_compatibility_rules','compatibility is configured as data');
select has_table('public','blood_bank_clinical_owners','facility review owner is assigned explicitly');
select has_table('public','blood_bank_witness_credentials','second verifier co-sign credentials are stored securely');
select has_table('public','blood_crossmatch_requests','crossmatch requests are recorded');
select has_table('public','blood_crossmatch_results','laboratory results are append only');
select has_table('public','blood_unit_events','unit lifecycle is traceable');
select has_table('public','transfusion_records','bedside transfusion records exist');
select has_table('public','transfusion_observations','timed vitals are append only');
select has_table('public','transfusion_reactions','reaction reporting is linked');
select has_view('public','blood_unit_inventory','inventory view derives current unit status');
select has_function('public','register_blood_unit',array['uuid','text','text','text','text','timestamp with time zone'],'units can be registered');
select has_function('public','assign_blood_bank_clinical_owner',array['uuid','uuid'],'clinical owner assignment is controlled');
select has_function('public','review_blood_compatibility_rule',array['uuid','integer','text','text','text','boolean'],'only assigned owner can review compatibility rules');
select has_function('public','record_blood_crossmatch',array['uuid','uuid','text'],'laboratory staff record a crossmatch result');
select has_function('public','issue_blood_unit',array['uuid','uuid','boolean'],'server verifies crossmatch before issue');
select has_function('public','return_blood_unit',array['uuid','boolean','text'],'unit return is timestamped and attributed');
select has_function('public','set_blood_bank_witness_pin',array['text'],'staff can enroll their own co-sign PIN');
select has_function('public','start_transfusion',array['uuid','uuid','uuid','uuid','uuid','text'],'bedside start requires a second verifier co-sign');
select has_function('public','begin_transfusion',array['uuid'],'transfusion starts only after a before-observation');
select has_function('public','complete_transfusion',array['uuid'],'completion requires all vital-sign phases');
select has_function('public','record_transfusion_observation',array['uuid','text','jsonb','text'],'before/during/after vitals are recorded');
select has_function('public','report_transfusion_reaction',array['uuid','text','jsonb'],'reaction is reportable');
select has_function('public','find_blood_unit_recall',array['text'],'recall query traces unit events to patient');
select ok(not has_table_privilege('authenticated','public.blood_units','INSERT'),'authenticated clients cannot bypass inventory RPC');
select ok(not has_table_privilege('authenticated','public.blood_unit_events','INSERT'),'authenticated clients cannot fabricate lifecycle events');
select ok(not has_table_privilege('authenticated','public.transfusion_records','INSERT'),'authenticated clients cannot bypass bedside workflow');
select has_trigger('public','blood_unit_events','blood_unit_events_immutable','unit events cannot be updated or deleted');
select has_trigger('public','transfusion_observations','transfusion_observations_immutable','observations cannot be updated or deleted');
select like(pg_get_functiondef('public.review_blood_compatibility_rule(uuid,integer,text,text,text,boolean)'::regprocedure),'%Only the assigned clinical owner may review compatibility rules%','unassigned actors are rejected from rule approval');
select like(pg_get_functiondef('public.record_blood_crossmatch(uuid,uuid,text)'::regprocedure),'%No clinically reviewed compatibility rule is configured for this pair%','missing rule blocks compatibility result');
select like(pg_get_functiondef('public.record_blood_crossmatch(uuid,uuid,text)'::regprocedure),'%Unit is not available or has expired%','expired or unavailable units are rejected');
select like(pg_get_functiondef('public.issue_blood_unit(uuid,uuid,boolean)'::regprocedure),'%Cold-chain acceptance is required%','issue requires cold-chain acceptance');
select like(pg_get_functiondef('public.issue_blood_unit(uuid,uuid,boolean)'::regprocedure),'%current reviewed rule version%','incompatible or stale-rule results block issue');
select like(pg_get_functiondef('public.start_transfusion(uuid,uuid,uuid,uuid,uuid,text)'::regprocedure),'%Two distinct authorized staff verifiers from this facility are required%','same-person or cross-facility verification is rejected');
select like(pg_get_functiondef('public.start_transfusion(uuid,uuid,uuid,uuid,uuid,text)'::regprocedure),'%Second verifier co-sign PIN is invalid or not configured%','unverified second-person co-sign is rejected');
select like(pg_get_functiondef('public.start_transfusion(uuid,uuid,uuid,uuid,uuid,text)'::regprocedure),'%Bedside patient, encounter, or facility verification failed%','wrong patient or encounter is rejected');
select like(pg_get_functiondef('public.complete_transfusion(uuid)'::regprocedure),'%Before, during, and after observations are required%','completion requires all observation phases');
select like(pg_get_functiondef('public.begin_transfusion(uuid)'::regprocedure),'%A before-transfusion observation is required before starting%','transfusion cannot begin without pre-vitals');
select is((select count(*)::integer from public.find_blood_unit_recall('NO-SUCH-UNIT')),0,'unauthenticated callers receive no recall trace data');
select * from finish();
rollback;
